  it('IMP04-10 · CON03/HU013-E3 · Perder confirmación y descarga → recupera la misma lectura y referencia sin duplicar la pista', () => {
    setup(0).then((context) => {
      const title = `Recibo-${crypto.randomUUID().slice(0, 8)}`;
      loadMaterial(context, title);
      submit(context).then((attempt) => {
        let lostAck = false,
          lostDownload = false;
        openAttempt(context, 1, (window) => {
          const original = window.fetch.bind(window);
          window.fetch = (input, init) =>
            original(input, init).then((response) => {
              const path = String(input);
              if (
                !lostAck &&
                path.endsWith('/viewed') &&
                init?.method === 'POST' &&
                response.status === 200
              ) {
                lostAck = true;
                throw new TypeError('Explicit TEST loss after real ACK commit');
              }
              if (
                !lostDownload &&
                /\/feedback\/[^/]+\/sources\/[^/]+\/content$/.test(path) &&
                response.status === 200
              ) {
                lostDownload = true;
                throw new TypeError('Explicit TEST download transport loss');
              }
              return response;
            });
        });
        cy.get('[data-cy="request-hint"]').should('be.enabled').click();
        cy.get('[data-cy="open-prepared-help"]', { timeout: 45_000 })
          .focus()
          .should('be.focused');
        pressEnterInChrome();
        cy.contains('No se pudo confirmar la lectura.').should('be.visible');
        cy.contains('button', 'Confirmar lectura').focus().should('be.focused');
        pressEnterInChrome();
        cy.contains('Lectura registrada.').should('be.visible');
        cy.get('[data-cy="request-hint"]').should(
          'contain.text',
          'Pedir pista 2 de 3',
        );
        cy.task<Array<{ type: string; count: number; level: number | null }>>(
          'help:events',
          { attemptId: attempt.attemptId },
          { log: false },
        ).then((events) =>
          expect(
            events.filter((event) => event.type === 'HINT_DELIVERED'),
          ).to.deep.equal([{ type: 'HINT_DELIVERED', level: 1, count: 1 }]),
        );
        cy.get('[data-cy="download-help-source"]').first().click();
        cy.contains(
          'No se pudo descargar el material. Vuelve a intentar.',
        ).should('be.visible');
        cy.then(() => expect(lostDownload).to.equal(true));
        cy.get('[data-cy="help-reference"]').should('contain.text', title);
        cy.intercept('GET', '**/api/v1/feedback/*/sources/*/content').as(
          'restoredDownload',
        );
        cy.get('[data-cy="download-help-source"]')
          .first()
          .should('be.enabled')
          .click();
        cy.wait('@restoredDownload')
          .its('response.statusCode')
          .should('equal', 200);
        cy.readFile(
          `.local/evidence/cypress-downloads/${title}.txt`,
          'utf8',
        ).should('equal', material);
        cy.reload();
        cy.contains('button', 'Ver intento #1').click();
        cy.get('[data-cy="help-detail"]').should('not.exist');
        show('Pista 1');
        cy.get('[data-cy="request-hint"]').should(
          'contain.text',
          'Pedir pista 2 de 3',
        );
        cy.contains('button', /^Cerrar sesión$/).click();
        cy.location('pathname').should('equal', '/acceso');
        cy.get('[data-cy="help-detail"]').should('not.exist');
      });
    });
  });
